fn get_git_dir_and_work_tree(cli: &Cli, config: &ClogConfig) -> (String, String) {
    let cwd = std::env::current_dir().unwrap_or_default();

    let (git_dir, work_tree) = if let (Some(gd), Some(wt)) = (&cli.git_dir, &cli.work_tree) {
        (gd.clone(), wt.clone())
    } else if let Some(gd) = &cli.git_dir {
        // Only git_dir specified - derive work_tree as parent
        let gd_path = Path::new(gd);
        let wt = gd_path.parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| cwd.to_string_lossy().to_string());
        (gd.clone(), wt)
    } else if let Some(wt) = &cli.work_tree {
        // Only work_tree specified - derive git_dir as child .git
        let gd = format!("{}/.git", wt);
        (gd, wt.clone())
    } else {
        // Derive from config path if possible
        let config_path = Path::new(&cli.config);
        let config_dir = if config_path.is_absolute() {
            config_path.parent()
                .map(|p| p.to_path_buf())
                .unwrap_or(cwd.clone())
        } else {
            cwd.clone()
        };
        let gd = format!("{}/.git", config_dir.to_string_lossy());
        let wt = config_dir.to_string_lossy().to_string();
        (gd, wt)
    };

    (git_dir, work_tree)
}

fn get_latest_tag_sha(git_dir: &str, work_tree: &str) -> String {
    let output = Command::new("git")
        .args(&[
            &format!("--git-dir={}", git_dir),
            &format!("--work-tree={}", work_tree),
            "rev-list",
            "--tags",
            "--max-count=1",
        ])
        .output();

    match output {
        Ok(out) if out.status.success() => {
            let sha = String::from_utf8_lossy(&out.stdout).to_string();
            sha.trim().to_string()
        }
        _ => String::new(),
    }
}

fn get_git_log(git_dir: &str, work_tree: &str, from: &str, to: &str) -> String {
    let range = if from.is_empty() {
        format!("{}..{}", "", to)
    } else {
        format!("{}..{}", from, to)
    };

    let grep_pattern = "^^ft|^feat||^^fx|^fix||^^perf||^^unk||^^breaks||BREAKING'";
    let format_str = "%H%n%s%n%b%n==END==";

    let output = Command::new("git")
        .args(&[
            &format!("--git-dir={}", git_dir),
            &format!("--work-tree={}", work_tree),
            "log",
            "-E",
            &format!("--grep={}", grep_pattern),
            &format!("--format={}", format_str),
            &range,
        ])
        .output();

    match output {
        Ok(out) if out.status.success() => {
            String::from_utf8_lossy(&out.stdout).to_string()
        }
        _ => String::new(),
    }
}

fn build_commit_url(repo: &str, link_style: &str, hash: &str) -> String {
    match link_style {
        "github" | "gitlab" => format!("{}/commit/{}", repo, hash),
        "stash" => format!("{}/commits/{}", repo, hash),
        "cgit" => format!("{}/commit/?id={}", repo, hash),
        _ => format!("{}/commit/{}", repo, hash),
    }
}

fn build_issue_url(repo: &str, link_style: &str, issue: u64) -> String {
    match link_style {
        "github" | "gitlab" => format!("{}/issues/{}", repo, issue),
        "stash" | "cgit" => format!("{}", issue),
        _ => format!("{}/issues/{}", repo, issue),
    }
}

fn parse_commits(
    git_log_output: &str,
    sections_map: &HashMap<String, Vec<String>>, // type -> section_name
    repo: &str,
    link_style: &str,
    use_repo_url: bool, // true if repo comes from CLI, false if from .clog.toml
) -> Vec<(String, Commit)> { // (section_name, commit)
    let mut result = Vec::new();

    // Subject regex: ^(type)(\(scope\))?:\s+(.+)$
    // Note: no support for "!" in current version
    let subject_re = Regex::new(r"^([^\s\(:/]+)(?:\(([^)]+)\))?:\s*(.+)$").unwrap();
    // Issue closing regex  
    let closes_re = Regex::new(r"(?i)clos(?:e[sd]?|ing)\s+#(\d+)").unwrap();
    // Breaking change regex
    let breaking_re = Regex::new(r"(?i)BREAKING CHANGE").unwrap();

    // Split on ==END==
    let commits_raw: Vec<&str> = git_log_output.split("\n==END==\n").collect();

    for commit_raw in commits_raw {
        let lines: Vec<&str> = commit_raw.splitn(3, '\n').collect();
        if lines.len() < 2 {
            continue;
        }

        let hash = lines[0].trim().to_string();
        if hash.is_empty() || hash.len() < 7 {
            continue;
        }

        let subject_line = lines[1];
        let body = if lines.len() > 2 { lines[2] } else { "" };

        // Parse subject
        let caps = match subject_re.captures(subject_line) {
            Some(c) => c,
            None => continue,
        };

        let commit_type = caps.get(1).map(|m| m.as_str()).unwrap_or("");
        let scope = caps.get(2).map(|m| m.as_str().to_string());
        let subject_desc = caps.get(3).map(|m| m.as_str()).unwrap_or("");

        // Find which section this commit belongs to
        let section_name = match sections_map.get(commit_type) {
            Some(s) => s.clone(),
            None => continue, // Skip unrecognized types
        };

        // Parse closes from body
        let closes_issues: Vec<Issue> = closes_re.captures_iter(body)
            .map(|c| {
                let issue_num: u64 = c.get(1).unwrap().as_str().parse().unwrap_or(0);
                let issue_link = if use_repo_url {
                    build_issue_url(repo, link_style, issue_num)
                } else {
                    format!("{}", issue_num)
                };
                Issue { issue: issue_num, issue_link }
            })
            .collect();

        // Check for breaking change
        let has_breaking = breaking_re.is_match(body);

        let breaks = if has_breaking {
            // Breaks = same issues as closes
            if closes_issues.is_empty() {
                Some(vec![])
            } else {
                Some(closes_issues.clone())
            }
        } else {
            None
        };

        let closes = if closes_issues.is_empty() {
            None
        } else {
            Some(closes_issues)
        };

        // Build commit link
        let short_hash = &hash[..8.min(hash.len())];
        let commit_link = if use_repo_url {
            build_commit_url(repo, link_style, &hash)
        } else {
            short_hash.to_string()
        };

        let commit = Commit {
            hash: hash.clone(),
            component: scope,
            subject: format!(" {}", subject_desc), // Add leading space as clog does
            closes,
            breaks,
            commit_link,
        };

        result.push((section_name, commit));
    }

    result
}

fn render_issue_link(issue: &Issue) -> String {
    format!("[#{}]({})", issue.issue, issue.issue_link)
}

fn render_commit_link_display(commit_link: &str) -> String {
    // If it's a URL, extract the hash from the path
    if commit_link.starts_with("http") {
        // The hash is the last path component
        let hash = commit_link.rsplit('/').next().unwrap_or(commit_link);
        // Take first 8 chars
        hash[..8.min(hash.len())].to_string()
    } else {
        commit_link.to_string()
    }
}

fn render_markdown(
    sections_config: &[(String, Vec<String>)], // ordered (section_name, types)
    commits_by_section: &HashMap<String, Vec<Commit>>,
    version: Option<&str>,
    patch_version: bool,
    subtitle: Option<&str>,
    date: &str,
    repo: &str,
    link_style: &str,
    use_repo_url: bool,
) -> String {
    let mut output = String::new();

    // Version anchor
    let version_str = version.unwrap_or("");
    writeln!(output, "<a name=\"{}\"></a>", version_str).unwrap();

    // Version header
    let heading = if patch_version { "###" } else { "##" };
    let subtitle_str = subtitle.unwrap_or("");
    writeln!(output, "{} {} {} ({})", heading, version_str, subtitle_str, date).unwrap();
    writeln!(output).unwrap();

    // Sections
    for (section_name, _types) in sections_config {
        if let Some(commits) = commits_by_section.get(section_name) {
            if commits.is_empty() {
                continue;
            }

            writeln!(output, "\n#### {}\n", section_name).unwrap();

            // Group commits by component
            let mut no_scope_commits: Vec<&Commit> = Vec::new();
            let mut scoped_commits: HashMap<String, Vec<&Commit>> = HashMap::new();

            for commit in commits {
                match &commit.component {
                    None => no_scope_commits.push(commit),
                    Some(scope) => {
                        scoped_commits.entry(scope.clone()).or_default().push(commit);
                    }
                }
            }

            // Write no-scope commits first
            for commit in &no_scope_commits {
                let link_display = render_commit_link_display(&commit.commit_link);
                let link_url = &commit.commit_link;
                let link_part = format!("([{}]({}))", link_display, link_url);

                let closes_part = render_closes_part(&commit.closes, use_repo_url);
                let breaks_part = render_breaks_part(&commit.breaks, use_repo_url);

                let extras = build_extras(closes_part, breaks_part);

                writeln!(output, "* {}{} ({}{})", " ", commit.subject, link_part, extras).unwrap();
            }

            // Write scoped commits alphabetically
            let mut scopes: Vec<String> = scoped_commits.keys().cloned().collect();
            scopes.sort();

            for scope in &scopes {
                let scope_commits = &scoped_commits[scope];

                if scope_commits.len() == 1 {
                    let commit = scope_commits[0];
                    let link_display = render_commit_link_display(&commit.commit_link);
                    let link_url = &commit.commit_link;
                    let link_part = format!("([{}]({}))", link_display, link_url);

                    let closes_part = render_closes_part(&commit.closes, use_repo_url);
                    let breaks_part = render_breaks_part(&commit.breaks, use_repo_url);
                    let extras = build_extras(closes_part, breaks_part);

                    writeln!(output, "* **{}:**{} ({}{})", scope, commit.subject, link_part, extras).unwrap();
                } else {
                    // Multiple commits - group under scope header
                    writeln!(output, "* **{}:**", scope).unwrap();

                    for commit in scope_commits.iter() {
                        let link_display = render_commit_link_display(&commit.commit_link);
                        let link_url = &commit.commit_link;
                        let link_part = format!("([{}]({}))", link_display, link_url);

                        let closes_part = render_closes_part(&commit.closes, use_repo_url);
                        let breaks_part = render_breaks_part(&commit.breaks, use_repo_url);
                        let extras = build_extras(closes_part, breaks_part);

                        writeln!(output, "  *{} ({}{})", commit.subject, link_part, extras).unwrap();
                    }
                }
            }
        }
    }

    output
}

fn render_closes_part(closes: &Option<Vec<Issue>>, use_repo_url: bool) -> String {
    match closes {
        None => String::new(),
        Some(issues) if issues.is_empty() => String::new(),
        Some(issues) => {
            let links: Vec<String> = issues.iter().map(|i| render_issue_link(i)).collect();
            let first = links[0].clone();
            let rest: Vec<String> = links[1..].to_vec();
            if rest.is_empty() {
                format!(", closes {}", first)
            } else {
                format!(", closes {}, {}", first, rest.join(", "))
            }
        }
    }
}

fn render_breaks_part(breaks: &Option<Vec<Issue>>, use_repo_url: bool) -> String {
    match breaks {
        None => String::new(),
        Some(issues) => {
            if use_repo_url {
                // When using repo URL, render breaks (with potential bug: empty issue number)
                let links: Vec<String> = issues.iter().map(|i| {
                    // Bug in original: displays "[#]" with empty issue number
                    format!("[#]({})", &i.issue_link[..i.issue_link.rfind(char::is_numeric).map(|p| p).unwrap_or(i.issue_link.len())].trim_end_matches(|c: char| c.is_numeric()))
                }).collect();
                if links.is_empty() {
                    // Empty breaks [] with no issues but BREAKING CHANGE present
                    // Still show "breaks [#](...issues/)" with empty issue
                    String::new()
                } else {
                    format!(", breaks {}", links.join(", "))
                }
            } else {
                // Without repo URL, breaks are not shown in markdown
                String::new()
            }
        }
    }
}

fn build_extras(closes_part: String, breaks_part: String) -> String {
    format!("{}{}", closes_part, breaks_part)
}

fn render_json(
    version: Option<&str>,
    patch_version: bool,
    subtitle: Option<&str>,
    date: &str,
    sections_config: &[(String, Vec<String>)],
    commits_by_section: &HashMap<String, Vec<Commit>>,
) -> String {
    let mut output = String::new();

    // Header
    let version_json = match version {
        Some(v) => format!("Some(\"{}\")", v),
        None => "None".to_string(),
    };
    let subtitle_json = match subtitle {
        Some(s) => format!("Some(\"{}\")", s),
        None => "null".to_string(),
    };

    write!(output, "{{\"header\":{{\"version\":{},\"patch_version\":{},\"subtitle\":{},\"date\":\"{}\"}}",
        version_json, patch_version, subtitle_json, date).unwrap();

    // Check if any sections have commits
    let has_sections = sections_config.iter().any(|(name, _)| {
        commits_by_section.get(name).map(|c| !c.is_empty()).unwrap_or(false)
    });

    if !has_sections {
        write!(output, ",\"sections\":null}}").unwrap();
        return output;
    }

    write!(output, ",\"sections\":[").unwrap();

    let mut first_section = true;
    for (section_name, _types) in sections_config {
        if let Some(commits) = commits_by_section.get(section_name) {
            if commits.is_empty() {
                continue;
            }

            if !first_section {
                write!(output, ",").unwrap();
            }
            first_section = false;

            write!(output, "{{\"title\":\"{}\",\"commits\":[", section_name).unwrap();

            let mut first_commit = true;
            for commit in commits {
                if !first_commit {
                    write!(output, ",").unwrap();
                }
                first_commit = false;

                let component_json = match &commit.component {
                    Some(s) => format!("\"{}\"", s),
                    None => "null".to_string(),
                };

                let closes_json = format_closes_json(&commit.closes);
                let breaks_json = format_breaks_json(&commit.breaks);

                write!(output, "{{\"component\":{},\"subject\":\"{}\",\"commit_link\":\"{}\",\"closes\":{},\"breaks\":{}}}",
                    component_json,
                    commit.subject.replace('"', "\\\""),
                    commit.commit_link,
                    closes_json,
                    breaks_json,
                ).unwrap();
            }

            write!(output, "]}}").unwrap();
        }
    }

    write!(output, "]}}").unwrap();
    output
}

fn format_closes_json(closes: &Option<Vec<Issue>>) -> String {
    match closes {
        None => "null".to_string(),
        Some(issues) if issues.is_empty() => "null".to_string(),
        Some(issues) => {
            let items: Vec<String> = issues.iter().map(|i| {
                format!("{{\"issue\":{},\"issue_link\":\"{}\"}}", i.issue, i.issue_link)
            }).collect();
            format!("[{}]", items.join(","))
        }
    }
}

fn format_breaks_json(breaks: &Option<Vec<Issue>>) -> String {
    match breaks {
        None => "null".to_string(),
        Some(issues) => {
            let items: Vec<String> = issues.iter().map(|i| {
                format!("{{\"issue\":{},\"issue_link\":\"{}\"}}", i.issue, i.issue_link)
            }).collect();
            format!("[{}]", items.join(","))
        }
    }
}

fn increment_version(base: &str, major: bool, minor: bool, patch: bool) -> Option<String> {
    // Parse semver: X.Y.Z
    let parts: Vec<&str> = base.split('.').collect();
    if parts.len() != 3 {
        return None;
    }
    let x: u64 = parts[0].parse().ok()?;
    let y: u64 = parts[1].parse().ok()?;
    let z: u64 = parts[2].parse().ok()?;

    if major {
        Some(format!("{}.0.0", x + 1))
    } else if minor {
        Some(format!("{}.{}.0", x, y + 1))
    } else if patch {
        Some(format!("{}.{}.{}", x, y, z + 1))
    } else {
        None
    }
}

fn get_version_from_git(git_dir: &str, work_tree: &str) -> String {
    let output = Command::new("git")
        .args(&[
            &format!("--git-dir={}", git_dir),
            &format!("--work-tree={}", work_tree),
            "describe",
            "--tags",
            "--abbrev=0",
        ])
        .output();

    match output {
        Ok(out) if out.status.success() => {
            // Note: we intentionally do NOT trim the newline (to replicate the bug in clog-lib)
            String::from_utf8_lossy(&out.stdout).to_string()
        }
        _ => String::new(),
    }
}

fn main() {
    let start = std::time::Instant::now();
    let cli = Cli::parse();

    // Read config file
    let config_content = match fs::read_to_string(&cli.config) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file");
            std::process::exit(1);
        }
    };

    let config: ClogConfig = match toml::from_str(&config_content) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse TOML configuration file");
            std::process::exit(1);
        }
    };

    // Determine git-dir and work-tree
    let (git_dir, work_tree) = get_git_dir_and_work_tree(&cli, &config);

    // Determine repository URL
    let repo_from_cli = cli.repository.is_some();
    let repository = cli.repository.clone()
        .or_else(|| config.clog.repository.clone())
        .unwrap_or_default();

    // Determine link style
    let link_style = cli.link_style.clone();

    // Determine from/to
    let use_from_latest_tag = cli.from_latest_tag || config.clog.from_latest_tag.unwrap_or(false);

    let from = if let Some(f) = &cli.from {
        f.clone()
    } else if use_from_latest_tag {
        if cli.from_latest_tag {
            // CLI flag: try first without git-dir (will fail), then with git-dir
            let _ = Command::new("git")
                .args(&["", "", "rev-list", "--tags", "--max-count=1"])
                .output();
            // Then get properly
            get_latest_tag_sha(&git_dir, &work_tree)
        } else {
            // From .clog.toml: only try without git-dir (which will fail)
            let output = Command::new("git")
                .args(&[
                    "--git-dir=",
                    "--work-tree=",
                    "rev-list",
                    "--tags",
                    "--max-count=1",
                ])
                .output();
            match output {
                Ok(out) if out.status.success() => {
                    String::from_utf8_lossy(&out.stdout).trim().to_string()
                }
                _ => String::new(),
            }
        }
    } else if let Some(f) = &config.clog.from {
        f.clone()
    } else {
        String::new()
    };

    let to = config.clog.to.as_deref().unwrap_or(&cli.to).to_string();
    let to = if to.is_empty() { "HEAD".to_string() } else { to };

    // Determine version
    let auto_version = cli.major || cli.minor || cli.patch;
    let (final_version, patch_version) = if let Some(sv) = &cli.setversion {
        (Some(sv.clone()), false)
    } else if auto_version {
        // Get current version from git describe
        let current_ver = get_version_from_git(&git_dir, &work_tree);
        // Parse (note: current_ver may have trailing newline = bug in original)
        let parsed = increment_version(current_ver.trim(), cli.major, cli.minor, cli.patch)
            .or_else(|| increment_version(&current_ver, cli.major, cli.minor, cli.patch));

        if parsed.is_none() {
            eprintln!("\x1b[1;31merror:\x1b[0m Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.");
            std::process::exit(1);
        }
        (parsed, cli.patch)
    } else if let Some(sv) = &config.clog.setversion {
        (Some(sv.clone()), false)
    } else {
        (None, false)
    };

    // Determine subtitle
    let subtitle = cli.subtitle.clone().or_else(|| config.clog.subtitle.clone());

    // Build sections map: type -> section_name
    let sections_config_raw = config.sections.clone().unwrap_or_default();
    let mut sections_map: HashMap<String, String> = HashMap::new(); // type -> section_name
    let mut sections_order: Vec<(String, Vec<String>)> = Vec::new(); // ordered

    for (section_name, types) in &sections_config_raw {
        sections_order.push((section_name.clone(), types.clone()));
        for t in types {
            sections_map.insert(t.clone(), section_name.clone());
        }
    }

    // Get git log
    let git_log = get_git_log(&git_dir, &work_tree, &from, &to);

    // Parse commits
    let parsed_commits = parse_commits(&git_log, &sections_map, &repository, &link_style, repo_from_cli);

    // Group commits by section (maintaining section order)
    let mut commits_by_section: HashMap<String, Vec<Commit>> = HashMap::new();
    for (section_name, commit) in parsed_commits {
        commits_by_section.entry(section_name).or_default().push(commit);
    }

    // Get current date
    let date = Local::now().format("%Y-%m-%d").to_string();

    // Generate output
    let changelog_content = if cli.format == "json" {
        render_json(
            final_version.as_deref(),
            patch_version,
            subtitle.as_deref(),
            &date,
            &sections_order,
            &commits_by_section,
        )
    } else {
        render_markdown(
            &sections_order,
            &commits_by_section,
            final_version.as_deref(),
            patch_version,
            subtitle.as_deref(),
            &date,
            &repository,
            &link_style,
            repo_from_cli,
        )
    };

    // Determine infile and outfile
    let infile = cli.infile.clone().or_else(|| config.clog.infile.clone());
    let outfile = cli.outfile.clone().or_else(|| config.clog.outfile.clone());
    let changelog_file = cli.changelog.clone().or_else(|| config.clog.changelog.clone());

    // Determine final infile and outfile
    let (final_infile, final_outfile): (Option<String>, Option<String>) = if let Some(cf) = changelog_file {
        (Some(cf.clone()), Some(cf))
    } else {
        (infile, outfile)
    };

    // Read existing content if infile specified
    let existing_content = if let Some(ref inf) = final_infile {
        fs::read_to_string(inf).unwrap_or_default()
    } else {
        String::new()
    };

    // Build full output
    let full_content = if existing_content.is_empty() {
        format!("{}\n\n\n", changelog_content)
    } else {
        format!("{}\n\n\n{}", changelog_content, existing_content)
    };

    // Write output
    if let Some(ref of_path) = final_outfile {
        match fs::write(of_path, &full_content) {
            Ok(_) => {},
            Err(_) => {
                eprintln!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file");
                std::process::exit(1);
            }
        }
    } else {
        print!("{}", changelog_content);
    }

    let elapsed = start.elapsed();
    let ms = elapsed.as_millis();
    eprintln!("changelog written. (took {} ms)", ms);
}
