fn get_git_dir_and_work_tree(cli: &Cli, config: &ClogConfig) -> (String, String) {
    let cwd = std::env::current_dir().unwrap_or_default();

    let (git_dir, work_tree) = if let (Some(gd), Some(wt)) = (&cli.git_dir, &cli.work_tree) {
        (gd.clone(), wt.clone())
    } else if let Some(gd) = &cli.git_dir {
        // Only git_dir specified - derive work_tree as parent
        let gd_path = Path::new(gd);
        let wt = gd_path.parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| cwd.to_string_lossy().to_string());
        (gd.clone(), wt)
    } else if let Some(wt) = &cli.work_tree {
        // Only work_tree specified - derive git_dir as child .git
        let gd = format!("{}/.git", wt);
        (gd, wt.clone())
    } else {
        // Derive from config path if possible
        let config_path = Path::new(&cli.config);
        let config_dir = if config_path.is_absolute() {
            config_path.parent()
                .map(|p| p.to_path_buf())
                .unwrap_or(cwd.clone())
        } else {
            cwd.clone()
        };
        let gd = format!("{}/.git", config_dir.to_string_lossy());
        let wt = config_dir.to_string_lossy().to_string();
        (gd, wt)
    };

    (git_dir, work_tree)
}

fn get_latest_tag_sha(git_dir: &str, work_tree: &str) -> String {
